$ErrorActionPreference='Stop';$out='evidence/issue-50/pinned-versions-audit.test.json';$script="$PSScriptRoot/audit-pinned-versions.ps1";$baseline=@(git status --porcelain);$protected=@('templates/opencode.v1.json.tmpl','templates/opencode.v2.json.tmpl','source/global/AGENTS.md')|Where-Object{Test-Path $_}|ForEach-Object{"$_`:$((Get-FileHash $_ -Algorithm SHA256).Hash)"}
try{& $script -OutFile $out -GeneratedAt fixed;$j=Get-Content $out -Raw|ConvertFrom-Json;if(@($j.declared_pins).Count -ne 5){throw 'expected five registry pins'};if(!$j.scan_scope -or !$j.excluded_paths){throw 'scope lists missing'};if(@($j.literals).Count -ne $j.counts.literals -or @($j.comparators).Count -ne $j.counts.comparators){throw 'counts mismatch'};foreach($l in $j.literals){if($l.classification -notin @('SOURCE_OF_TRUTH','DUPLICATE_LITERAL','MESSAGE_ONLY','VERSION_COMPARATOR')){throw 'bad literal class'}};$first=Get-Content $out -Raw;& $script -OutFile $out -GeneratedAt fixed;if($first -ne (Get-Content $out -Raw)){throw 'not deterministic'};$after=@('templates/opencode.v1.json.tmpl','templates/opencode.v2.json.tmpl','source/global/AGENTS.md')|Where-Object{Test-Path $_}|ForEach-Object{"$_`:$((Get-FileHash $_ -Algorithm SHA256).Hash)"};if(($protected -join '|') -ne ($after -join '|')){throw 'protected file changed'};$changed=@(git status --porcelain|Where-Object{$_ -notmatch [regex]::Escape($out)});if(($changed -join "`n") -ne ($baseline -join "`n")){throw 'write outside OutFile'};'PASS audit-pinned-versions'}finally{Remove-Item $out -ErrorAction SilentlyContinue}
